var t=`0363-topfenknodel`;var n=`world-0363`;var o=`AT`;var r=`western-europe`;var s=8;var l=67;var a={en:`Topfenknödel`,ua:`Сирні кнедлики`};var g={en:`A traditional Austria dish made with quark, chicken egg, semolina flour, lemon zest. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Австрія. Основні інгредієнти: кварк, куряче яйце, семоліна, цедра лимона. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`quark`,500,`g`],[`chicken-egg`,2,`pcs`],[`semolina-flour`,110,`g`],[`lemon-zest`,6,`g`],[`white-granulated-sugar`,90,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 25 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 25 хвилин.`,t:[`rapid-chilling`],m:25,i:[]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:12,i:[]},{en:`Cook dumplings in batches in gently boiling salted water for about 12 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 12 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:12,i:[[`water`,1300,`ml`]]},{en:`Toast these ingredients over medium heat for about 7 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 7 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:7,i:[[`breadcrumbs`,150,`g`],[`unsalted-butter`,80,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`powdered-sugar`,35,`g`]]}];var d={slug:t,id:n,country:`AT`,region:r,servings:8,minutes:67,title:a,text:g,steps:u};export{o as country,d as default,n as id,l as minutes,r as region,s as servings,t as slug,u as steps,g as text,a as title};